import { Router } from "express";
import { z } from "zod";
import { prisma } from "../../lib/prisma.js";
import { authenticate } from "../auth/auth.middleware.js";
import { withTenantContext } from "../auth/tenant-context.js";
import { hasSchoolAdminAccess } from "../organizations/organization.authorization.js";
import { hasSchoolPermission } from "../auth/school-permissions.js";
import { hasActiveSchoolMembership } from "../schools/school-config.authorization.js";
import { parseTimetableCsv, serializeTimetableCsv } from "./timetable-csv.js";
import { buildLegacyRoomUsageReport, normalizeRoomAliasLabel } from "./room-lifecycle.js";

export const teacherTimetableRouter = Router();
teacherTimetableRouter.use(authenticate);
const asyncRoute = (fn: (req:any,res:any)=>Promise<unknown>) => (req:any,res:any,next:any)=>Promise.resolve(fn(req,res)).catch(next);
const dateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine(v=>{const d=new Date(`${v}T00:00:00.000Z`);return !Number.isNaN(d.valueOf())&&d.toISOString().slice(0,10)===v;});
const slotSchema = z.object({teacherAssignmentId:z.string().min(1),academicYearId:z.string().min(1),dayOfWeek:z.number().int().min(1).max(7),periodNumber:z.number().int().min(1).max(20),startsAt:z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/),endsAt:z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/),subjectName:z.string().trim().min(1).max(100).optional(),room:z.string().trim().max(50).optional(),effectiveFrom:dateSchema.optional(),effectiveTo:dateSchema.optional()}).refine(v=>v.startsAt<v.endsAt,{message:"End time must be after start time",path:["endsAt"]}).refine(v=>!v.effectiveFrom||!v.effectiveTo||v.effectiveFrom<=v.effectiveTo,{message:"Effective date range is invalid",path:["effectiveTo"]});
async function canonicalRoomCode(tx:any, ctx:any, value?:string|null):Promise<string|null|undefined> {
 if(value===undefined)return undefined; if(value===null||!value.trim())return null;
 const code=value.trim().toUpperCase();
 const room=await tx.schoolRoom.findFirst({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,code,isActive:true},select:{code:true}});
 return room?.code ?? "__INVALID_ROOM_CODE__";
}
async function scope(req:any,res:any){const organizationId=String(req.params.organizationId||""),schoolId=String(req.params.schoolId||""),userId=req.auth!.userId;if(!await hasActiveSchoolMembership(userId,organizationId,schoolId)){res.status(403).json({error:"Active school membership required"});return null;}return {organizationId,schoolId,userId};}
async function canManageTimetable(userId:string,organizationId:string,schoolId:string){
 return await hasSchoolAdminAccess(userId,organizationId,schoolId) || await hasSchoolPermission(userId,organizationId,schoolId,"academics.manage");
}

// Teacher's own daily timetable. The date is school-local calendar date supplied by the client.
teacherTimetableRouter.get("/:organizationId/:schoolId/teacher/me/timetable",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;
 const parsed=dateSchema.safeParse(req.query.date);if(!parsed.success)return res.status(400).json({error:"A valid date=YYYY-MM-DD is required"});
 const date=new Date(`${parsed.data}T00:00:00.000Z`);const dayOfWeek=((date.getUTCDay()+6)%7)+1;const next=new Date(date);next.setUTCDate(next.getUTCDate()+1);
 const data=await withTenantContext(prisma,ctx,async tx=>{
  const staff=await tx.staffMember.findFirst({where:{userId:ctx.userId,organizationId:ctx.organizationId,schoolId:ctx.schoolId,status:"ACTIVE"},select:{id:true}});
  if(!staff)return null;
  const assignments=await tx.teacherAssignment.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,staffMemberId:staff.id,isActive:true,OR:[{startsOn:null},{startsOn:{lte:date}}],AND:[{OR:[{endsOn:null},{endsOn:{gte:date}}]}]},select:{id:true,academicYearId:true,gradeLevelId:true,sectionName:true}});
  const assignmentIds=assignments.map(a=>a.id);
  const [slots,events,attendanceSessions]=await Promise.all([
   tx.teacherTimetableSlot.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,teacherAssignmentId:{in:assignmentIds},academicYearId:{in:assignments.map(a=>a.academicYearId)},dayOfWeek,isActive:true,OR:[{effectiveFrom:null},{effectiveFrom:{lte:date}}],AND:[{OR:[{effectiveTo:null},{effectiveTo:{gte:date}}]}]},orderBy:[{startsAt:"asc"},{periodNumber:"asc"}]}),
   tx.calendarEvent.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,startsAt:{lt:next},endsAt:{gte:date},audience:{in:["ALL","STAFF"]}},select:{id:true,title:true,eventType:true,startsAt:true,endsAt:true,isAllDay:true,isInstructionDay:true,location:true},orderBy:{startsAt:"asc"},take:50}),
   tx.attendanceSession.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,sessionDate:date,OR:assignments.map(a=>({academicYearId:a.academicYearId,gradeLevelId:a.gradeLevelId,sectionName:a.sectionName}))},select:{id:true,academicYearId:true,gradeLevelId:true,sectionName:true,status:true},orderBy:{createdAt:"asc"},take:100})
  ]);
  const assignmentById=new Map(assignments.map(a=>[a.id,a]));
  const substituteExceptions=assignmentIds.length?await tx.teacherTimetableException.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,exceptionDate:date,isActive:true,exceptionType:"SUBSTITUTE",substituteAssignmentId:{in:assignmentIds}}}):[];
  const extraSlotIds=substituteExceptions.map(item=>item.timetableSlotId).filter(id=>!slots.some(slot=>slot.id===id));
  const extraSlots=extraSlotIds.length?await tx.teacherTimetableSlot.findMany({where:{id:{in:extraSlotIds},organizationId:ctx.organizationId,schoolId:ctx.schoolId,isActive:true}}):[];
  const allSlots=[...slots,...extraSlots];
  const exceptions=await tx.teacherTimetableException.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,exceptionDate:date,isActive:true,timetableSlotId:{in:allSlots.map(slot=>slot.id)}}});
  const exceptionBySlot=new Map(exceptions.map(item=>[item.timetableSlotId,item]));
  const substituteIds=exceptions.flatMap(item=>item.substituteAssignmentId?[item.substituteAssignmentId]:[]);
  const substituteAssignments=substituteIds.length?await tx.teacherAssignment.findMany({where:{id:{in:substituteIds},organizationId:ctx.organizationId,schoolId:ctx.schoolId},select:{id:true,staffMemberId:true,gradeLevelId:true,sectionName:true}}):[];
  const substituteById=new Map(substituteAssignments.map(a=>[a.id,a]));
  const visibleSlots=allSlots.filter(slot=>{const exception=exceptionBySlot.get(slot.id);if(exception?.exceptionType==="SUBSTITUTE")return !!exception.substituteAssignmentId&&assignmentIds.includes(exception.substituteAssignmentId);return assignmentIds.includes(slot.teacherAssignmentId);}).map(slot=>{const exception=exceptionBySlot.get(slot.id)||null;const isSubstitute=!!exception?.substituteAssignmentId&&assignmentIds.includes(exception.substituteAssignmentId);return {...slot,assignment:isSubstitute?assignmentById.get(exception!.substituteAssignmentId!)||null:assignmentById.get(slot.teacherAssignmentId)||null,exception,isSubstitute,substituteAssignment:exception?.substituteAssignmentId?substituteById.get(exception.substituteAssignmentId)||null:null,cancelled:exception?.exceptionType==="CANCEL",displayStartsAt:exception?.startsAt||slot.startsAt,displayEndsAt:exception?.endsAt||slot.endsAt,displayRoom:exception?.room||slot.room};});
  const schoolClosed=events.some(event=>(event.eventType==="HOLIDAY"||event.eventType==="CLOSURE")&&!event.isInstructionDay);
  return {date:parsed.data,dayOfWeek,schoolClosed,slots:schoolClosed?[]:visibleSlots.filter(slot=>!slot.cancelled),cancelledSlots:visibleSlots.filter(slot=>slot.cancelled),events,attendanceSessions};
 });
 if(!data)return res.status(403).json({error:"Active linked teacher profile required"});
 return res.json({data});
}));

// School administrator timetable setup; slots can only be attached to assignments in this school.
teacherTimetableRouter.get("/:organizationId/:schoolId/timetable/slots",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;if(!await canManageTimetable(ctx.userId,ctx.organizationId,ctx.schoolId))return res.status(403).json({error:"Timetable management permission required"});
 const slots=await withTenantContext(prisma,ctx,tx=>tx.teacherTimetableSlot.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,isActive:true,...(req.query.academicYearId?{academicYearId:String(req.query.academicYearId)}:{})},orderBy:[{dayOfWeek:"asc"},{startsAt:"asc"}],take:1000}));return res.json({data:slots});
}));
teacherTimetableRouter.post("/:organizationId/:schoolId/timetable/slots",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;if(!await canManageTimetable(ctx.userId,ctx.organizationId,ctx.schoolId))return res.status(403).json({error:"Timetable management permission required"});
 const parsed=slotSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:"Invalid timetable slot",details:parsed.error.flatten()});
 const input=parsed.data;
 const result=await withTenantContext(prisma,ctx,async tx=>{
  await acquireTimetableWriteLock(tx,ctx,input.academicYearId);
  const canonicalRoom=await canonicalRoomCode(tx,ctx,input.room); if(canonicalRoom==="__INVALID_ROOM_CODE__")return {invalidRoom:true};
  const assignment=await tx.teacherAssignment.findFirst({where:{id:input.teacherAssignmentId,organizationId:ctx.organizationId,schoolId:ctx.schoolId,academicYearId:input.academicYearId,isActive:true},select:{id:true,staffMemberId:true}});if(!assignment)return null;
  const teacherAssignments=await tx.teacherAssignment.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,staffMemberId:assignment.staffMemberId,academicYearId:input.academicYearId,isActive:true},select:{id:true}});
  const collisionScopes:any[]=[{teacherAssignmentId:{in:teacherAssignments.map(a=>a.id)}}];if(canonicalRoom)collisionScopes.push({room:canonicalRoom});
  const overlaps=await tx.teacherTimetableSlot.findFirst({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,academicYearId:input.academicYearId,dayOfWeek:input.dayOfWeek,isActive:true,startsAt:{lt:input.endsAt},endsAt:{gt:input.startsAt},AND:[{OR:[{effectiveTo:null},{effectiveTo:{gte:input.effectiveFrom?new Date(input.effectiveFrom):new Date("0001-01-01")}}]},{OR:[{effectiveFrom:null},{effectiveFrom:{lte:input.effectiveTo?new Date(input.effectiveTo):new Date("9999-12-31")}}]},{OR:collisionScopes}]},select:{id:true}});if(overlaps)return {conflict:true};
  return tx.teacherTimetableSlot.create({data:{...input,room:canonicalRoom,organizationId:ctx.organizationId,schoolId:ctx.schoolId,createdBy:ctx.userId,effectiveFrom:input.effectiveFrom?new Date(input.effectiveFrom):undefined,effectiveTo:input.effectiveTo?new Date(input.effectiveTo):undefined}});
 });
 if(!result)return res.status(400).json({error:"Active teacher assignment not found in this school and academic year"});if("invalidRoom" in result)return res.status(400).json({error:"Room must be an active canonical room code from this school"});if("conflict" in result)return res.status(409).json({error:"The teacher or room already has an overlapping slot for this weekday and effective date range"});return res.status(201).json({data:result});
}));


// P19 shared validation helpers. All writes remain inside tenant context.
function dateRangesOverlap(aFrom?: string, aTo?: string, bFrom?: string, bTo?: string) {
 const min="0001-01-01", max="9999-12-31";
 return (aFrom||min) <= (bTo||max) && (bFrom||min) <= (aTo||max);
}
function clockRangesOverlap(aStart:string,aEnd:string,bStart:string,bEnd:string) {
 return aStart < bEnd && aEnd > bStart;
}
async function acquireTimetableWriteLock(tx:any, ctx:any, academicYearId:string) {
 // School-wide lock coordinates room lifecycle with all timetable writers; the
 // second lock preserves the existing academic-year serialization boundary.
 await tx.$queryRawUnsafe("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", `${ctx.organizationId}:${ctx.schoolId}`);
 await tx.$queryRawUnsafe("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", `${ctx.organizationId}:${ctx.schoolId}:${academicYearId}`);
}
async function findSlotConflict(tx:any, ctx:any, input:any, excludeId?:string) {
 const assignment=await tx.teacherAssignment.findFirst({where:{id:input.teacherAssignmentId,organizationId:ctx.organizationId,schoolId:ctx.schoolId,academicYearId:input.academicYearId,isActive:true},select:{id:true,staffMemberId:true}});
 if(!assignment)return {kind:"ASSIGNMENT" as const};
 const peerAssignments=await tx.teacherAssignment.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,academicYearId:input.academicYearId,staffMemberId:assignment.staffMemberId,isActive:true},select:{id:true}});
 const peerIds=peerAssignments.map((a:any)=>a.id);
 const peers=await tx.teacherTimetableSlot.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,academicYearId:input.academicYearId,dayOfWeek:input.dayOfWeek,isActive:true,...(excludeId?{id:{not:excludeId}}:{})},select:{id:true,teacherAssignmentId:true,startsAt:true,endsAt:true,room:true,effectiveFrom:true,effectiveTo:true}});
 for(const existing of peers){
  const sameTeacher=peerIds.includes(existing.teacherAssignmentId);
  const sameRoom=!!input.room && !!existing.room && input.room.trim().toLocaleLowerCase()===existing.room.trim().toLocaleLowerCase();
  if((sameTeacher||sameRoom) && clockRangesOverlap(input.startsAt,input.endsAt,existing.startsAt,existing.endsAt) && dateRangesOverlap(input.effectiveFrom,input.effectiveTo,existing.effectiveFrom?.toISOString().slice(0,10),existing.effectiveTo?.toISOString().slice(0,10)))
   return {kind:sameTeacher?"TEACHER":"ROOM" as const, conflictingSlotId:existing.id};
 }
 return null;
}
const updateSlotSchema=z.object({teacherAssignmentId:z.string().min(1),academicYearId:z.string().min(1),dayOfWeek:z.number().int().min(1).max(7),periodNumber:z.number().int().min(1).max(20),startsAt:z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/),endsAt:z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/),subjectName:z.string().trim().min(1).max(100),room:z.string().trim().max(50).nullable(),effectiveFrom:dateSchema.nullable(),effectiveTo:dateSchema.nullable()}).partial().refine(v=>Object.keys(v).length>0,{message:"At least one field is required"});
const bulkSchema=z.object({slots:z.array(slotSchema).min(1).max(500),mode:z.enum(["VALIDATE","IMPORT"]).default("VALIDATE")});

// P19: update a slot after revalidating the complete merged record.
teacherTimetableRouter.patch("/:organizationId/:schoolId/timetable/slots/:slotId",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;if(!await canManageTimetable(ctx.userId,ctx.organizationId,ctx.schoolId))return res.status(403).json({error:"Timetable management permission required"});
 const parsed=updateSlotSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:"Invalid timetable update",details:parsed.error.flatten()});
 const result=await withTenantContext(prisma,ctx,async tx=>{
  const current=await tx.teacherTimetableSlot.findFirst({where:{id:req.params.slotId,organizationId:ctx.organizationId,schoolId:ctx.schoolId,isActive:true}});if(!current)return {kind:"NOT_FOUND" as const};
  const merged={teacherAssignmentId:parsed.data.teacherAssignmentId??current.teacherAssignmentId,academicYearId:parsed.data.academicYearId??current.academicYearId,dayOfWeek:parsed.data.dayOfWeek??current.dayOfWeek,periodNumber:parsed.data.periodNumber??current.periodNumber,startsAt:parsed.data.startsAt??current.startsAt,endsAt:parsed.data.endsAt??current.endsAt,subjectName:parsed.data.subjectName??current.subjectName,room:Object.prototype.hasOwnProperty.call(parsed.data,"room")?parsed.data.room:current.room,effectiveFrom:Object.prototype.hasOwnProperty.call(parsed.data,"effectiveFrom")?(parsed.data.effectiveFrom||undefined):current.effectiveFrom?.toISOString().slice(0,10),effectiveTo:Object.prototype.hasOwnProperty.call(parsed.data,"effectiveTo")?(parsed.data.effectiveTo||undefined):current.effectiveTo?.toISOString().slice(0,10)};
  await acquireTimetableWriteLock(tx,ctx,merged.academicYearId);
  if(Object.prototype.hasOwnProperty.call(parsed.data,"room")){const canonical=await canonicalRoomCode(tx,ctx,parsed.data.room);if(canonical==="__INVALID_ROOM_CODE__")return {kind:"INVALID_ROOM" as const};merged.room=canonical;}
  if(merged.startsAt>=merged.endsAt || (merged.effectiveFrom&&merged.effectiveTo&&merged.effectiveFrom>merged.effectiveTo))return {kind:"INVALID_RANGE" as const};
  const conflict=await findSlotConflict(tx,ctx,merged, current.id);if(conflict)return {kind:"CONFLICT" as const,conflict};
  return {kind:"UPDATED" as const,data:await tx.teacherTimetableSlot.update({where:{id:current.id},data:{...parsed.data,...(Object.prototype.hasOwnProperty.call(parsed.data,"effectiveFrom")?{effectiveFrom:parsed.data.effectiveFrom?new Date(parsed.data.effectiveFrom):null}:{}),...(Object.prototype.hasOwnProperty.call(parsed.data,"effectiveTo")?{effectiveTo:parsed.data.effectiveTo?new Date(parsed.data.effectiveTo):null}:{})}})};
 });
 if(result.kind==="NOT_FOUND")return res.status(404).json({error:"Timetable slot not found"});if(result.kind==="INVALID_RANGE")return res.status(400).json({error:"Invalid time or effective date range"});if(result.kind==="INVALID_ROOM")return res.status(400).json({error:"Room must be an active canonical room code from this school"});if(result.kind==="CONFLICT")return res.status(409).json({error:"Teacher or room timetable conflict",details:result.conflict});return res.json({data:result.data});
}));

// P19: validate or import a batch. Validation is all-or-nothing; no partial inserts.
teacherTimetableRouter.post("/:organizationId/:schoolId/timetable/slots/bulk",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;if(!await canManageTimetable(ctx.userId,ctx.organizationId,ctx.schoolId))return res.status(403).json({error:"Timetable management permission required"});
 const parsed=bulkSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:"Invalid timetable batch",details:parsed.error.flatten()});
 const result=await withTenantContext(prisma,ctx,async tx=>{
  const yearIds=[...new Set(parsed.data.slots.map(item=>item.academicYearId))].sort();for(const yearId of yearIds)await acquireTimetableWriteLock(tx,ctx,yearId);
  const conflicts:any[]=[];const staged:any[]=[];
  for(let i=0;i<parsed.data.slots.length;i++){
   const item=parsed.data.slots[i];
   const canonicalRoom=await canonicalRoomCode(tx,ctx,item.room);if(canonicalRoom==="__INVALID_ROOM_CODE__"){conflicts.push({row:i+1,kind:"INVALID_ROOM_CODE"});staged.push(item);continue;}item.room=canonicalRoom||undefined;
   const assignment=await tx.teacherAssignment.findFirst({where:{id:item.teacherAssignmentId,organizationId:ctx.organizationId,schoolId:ctx.schoolId,academicYearId:item.academicYearId,isActive:true},select:{id:true,staffMemberId:true}});
   if(!assignment){conflicts.push({row:i+1,kind:"INVALID_ASSIGNMENT"});staged.push(item);continue;}
   const duplicate=staged.find((prior:any)=>prior.dayOfWeek===item.dayOfWeek&&prior.academicYearId===item.academicYearId&&clockRangesOverlap(item.startsAt,item.endsAt,prior.startsAt,prior.endsAt)&&dateRangesOverlap(item.effectiveFrom,item.effectiveTo,prior.effectiveFrom,prior.effectiveTo)&&(prior.staffMemberId===assignment.staffMemberId || (!!item.room&&!!prior.room&&item.room===prior.room)));
   const conflict=await findSlotConflict(tx,ctx,item);
   if(duplicate)conflicts.push({row:i+1,kind:"BATCH_DUPLICATE",conflictsWith:staged.indexOf(duplicate)+1});
   if(conflict)conflicts.push({row:i+1,...conflict});
   staged.push({...item,staffMemberId:assignment.staffMemberId});
  }
  if(conflicts.length || parsed.data.mode==="VALIDATE")return {valid:conflicts.length===0,conflicts,created:0};
  const created=await tx.teacherTimetableSlot.createMany({data:staged.map((item:any)=>{const {staffMemberId,...slot}=item;return {...slot,organizationId:ctx.organizationId,schoolId:ctx.schoolId,createdBy:ctx.userId,effectiveFrom:item.effectiveFrom?new Date(item.effectiveFrom):undefined,effectiveTo:item.effectiveTo?new Date(item.effectiveTo):undefined};})});
  return {valid:true,conflicts:[],created:created.count};
 });
 if(!result.valid)return res.status(409).json({data:result});return res.status(parsed.data.mode==="IMPORT"?201:200).json({data:result});
}));

// P19: machine-readable export; consumers can save as CSV/JSON without leaking other tenants.
teacherTimetableRouter.get("/:organizationId/:schoolId/timetable/slots/export",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;if(!await canManageTimetable(ctx.userId,ctx.organizationId,ctx.schoolId))return res.status(403).json({error:"Timetable management permission required"});
 const rows=await withTenantContext(prisma,ctx,tx=>tx.teacherTimetableSlot.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,isActive:true,...(req.query.academicYearId?{academicYearId:String(req.query.academicYearId)}:{})},orderBy:[{dayOfWeek:"asc"},{startsAt:"asc"}],take:5000}));
 return res.json({data:rows,meta:{count:rows.length,format:"json",truncated:rows.length===5000}});
}));

teacherTimetableRouter.delete("/:organizationId/:schoolId/timetable/slots/:slotId",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;if(!await canManageTimetable(ctx.userId,ctx.organizationId,ctx.schoolId))return res.status(403).json({error:"Timetable management permission required"});
 const result=await withTenantContext(prisma,ctx,tx=>tx.teacherTimetableSlot.updateMany({where:{id:req.params.slotId,organizationId:ctx.organizationId,schoolId:ctx.schoolId,isActive:true},data:{isActive:false}}));if(!result.count)return res.status(404).json({error:"Timetable slot not found"});return res.json({data:{deactivated:true}});
}));


// P20 canonical room inventory.
const roomSchema=z.object({code:z.string().trim().min(1).max(30).regex(/^[A-Za-z0-9_-]+$/),name:z.string().trim().min(1).max(100),roomType:z.string().trim().max(50).optional(),capacity:z.number().int().positive().max(5000).optional(),floor:z.string().trim().max(30).optional()});
teacherTimetableRouter.get("/:organizationId/:schoolId/timetable/rooms",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;if(!await canManageTimetable(ctx.userId,ctx.organizationId,ctx.schoolId))return res.status(403).json({error:"Timetable management permission required"});
 const rooms=await withTenantContext(prisma,ctx,tx=>tx.schoolRoom.findMany({where:{organizationId:ctx.organizationId,schoolId:ctx.schoolId,...(req.query.includeInactive==="true"?{}:{isActive:true})},orderBy:{code:"asc"},take:500}));return res.json({data:rooms});
}));
teacherTimetableRouter.post("/:organizationId/:schoolId/timetable/rooms",asyncRoute(async(req,res)=>{
 const ctx=await scope(req,res);if(!ctx)return;if(!await canManageTimetable(ctx.userId,ctx.organizationId,ctx.schoolId))return res.status(403).json({error:"Timetable management permission required"});
 const parsed=roomSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:"Invalid room",details:parsed.error.flatten()});
 const room=await withTenantContext(prisma,ctx,tx=>tx.schoolRoom.create({data:{...parsed.data,code:parsed.data.code.toUpperCase(),organizationId:ctx.organizationId,schoolId:ctx.schoolId,createdBy:ctx.userId}}).catch((error:any)=>{if(error?.code==="P2002")return null;throw error;}));if(!room)return res.status(409).json({error:"Room code already exists in this school"});return res.status(201).json({data:room});
}));
// P22 room lifecycle: codes are immutable once created because timetable slots
// currently retain the canonical code as a scalar. Metadata and activation are editable.
const roomPatchSchema=z.object({name:z.string().trim().min(1).max(100).optional(),roomType:z.string().trim().max(50).nullable().optional(),capacity:z.number().int().positive().max(5000).nullable().optional(),floor:z.string().trim().max(30).nullable().optional(),isActive:z.boolean().optional()}).refine(v=>Object.keys(v).length>0,{message:"At least one room field is required"});
// P22: non-destructive inventory of historical free-text room labels. No rows are rewritten.
