 const input=z.object({academicYearId:z.string().min(1),teacherAssignmentIds:z.array(z.string().min(1)).min(1).max(100),days:z.array(z.number().int().min(1).max(7)).min(1).max(7),subjectName:z.string().trim().min(1).max(100).optional(),room:z.string().trim().max(50).optional(),effectiveFrom:dateSchema.optional(),effectiveTo:dateSchema.optional()}).refine(v=>!v.effectiveFrom||!v.effectiveTo||v.effectiveFrom<=v.effectiveTo).safeParse(req.body);if(!input.success)return res.status(400).json({error:"Invalid template application",details:input.error.flatten()});
